// ---------------------------------------------------------------------------
// video_capture_wrap - OV5640 SCCB configuration + DVP 8->16 capture
//
//   clk_27m  : power-on delay (vendor power_on_delay)
//   clk_cam  : SCCB register configuration (vendor reg_config, ~24.75 MHz)
//   cam_pclk : DVP byte clock (84 MHz)
//   pixel_clk: cam_pclk / 2, generated by video_dvp_rgb565
//
// The I2C/SCCB FSM is bypassed under VIDEO_SIM so the DVP/counter unit test can
// run without an OV5640 slave model.  PDS builds the real FSM.
// ---------------------------------------------------------------------------
`include "video_defs.vh"

module video_capture_wrap #(
    // OV5640 reg 0x4300 = 0x60 (reg_config index 156) selects RGB565 output
    // sequence 0: first byte {B[4:0],G[5:3]}, second {G[2:0],R[4:0]}.
    // video_dvp_rgb565 packs them as {first,second} = {B,G,R}, so the validated
    // vendor/Gowin mapping {d[4:0],d[10:5],d[15:11]} gives {R,G,B}.
    // Set to 0 only for a sensor configured RGB-first.
    parameter integer RGB_SWAP = 1,
    // The vendor power-on sequencer ends in a register that PDS maps onto the
    // constant VCC net, so two instances of this wrapper collide on that net
    // ("_$$_VCC_$$_ has multiple drivers").  Only the first camera runs the
    // sequencer; the second just follows the system reset.
    parameter integer USE_POWER_ON = 1
) (
    input  wire        clk_27m,
    input  wire        clk_cam,
    input  wire        rst_sys,          // active high
    output wire        cam_reset,        // active low
    inout  wire        cam_scl,
    inout  wire        cam_sda,
    input  wire        cam_rst_ext,      // reset release from the shared sequencer
    input  wire        cam_pclk,
    input  wire        cam_vsync,
    input  wire        cam_href,
    input  wire [7:0]  cam_data,
    output wire        pixel_clk,        // 42 MHz
    output wire        pixel_rst,        // active high
    output wire        pixel_vsync,
    output wire        pixel_de,
    output wire [15:0] pixel_rgb565,
    output wire        cam_init_done,
    output wire [31:0] dbg_vsync_cnt,
    output wire [31:0] dbg_line_cnt,
    output wire [31:0] dbg_pixel_cnt,
    output wire [31:0] dbg_pclk_cnt
);

    wire        cam_reset_i;
    wire        cam_init_done_i;
    wire        pixel_clk_i;

`ifdef VIDEO_SIM
    assign cam_reset_i    = 1'b1;
    assign cam_init_done_i = 1'b1;
    /* verilator lint_off UNUSEDSIGNAL */
    wire _unused_ext = &{1'b0, cam_rst_ext};
    /* verilator lint_on UNUSEDSIGNAL */
    assign cam_scl        = 1'b1;
    assign cam_sda        = 1'bz;
    /* verilator lint_off UNUSEDSIGNAL */
    wire _unused_sim = &{1'b0, clk_27m, clk_cam, rst_sys};
    /* verilator lint_on UNUSEDSIGNAL */
`else
    wire camera_pwnd_unused;
    wire initial_en_unused;

    generate
    if (USE_POWER_ON != 0) begin : g_power
        power_on_delay u_power (
            .clk_50M      (clk_27m),
            .reset_n      (~rst_sys),
            .camera1_rstn (cam_reset_i),
            .camera2_rstn (),
            .camera_pwnd  (camera_pwnd_unused),
            .initial_en   (initial_en_unused)
        );
    end else begin : g_nopower
        // cmos2 shares the power rail and the sequencer with cmos1, so it just
        // takes that reset release as an input.  Generating a second one is
        // what PDS rejects: a register that settles at 1 is mapped onto its
        // VCC net, and two such drivers collide ("_\$\$_VCC_\$\$_").
        assign cam_reset_i        = cam_rst_ext;
        assign camera_pwnd_unused = 1'b0;
        assign initial_en_unused  = 1'b1;
    end
    endgenerate

    reg_config u_reg_config (
        .clk_25M      (clk_cam),
        .camera_rstn  (cam_reset_i),
        .initial_en   (1'b1),
        .reg_conf_done(cam_init_done_i),
        .i2c_sclk     (cam_scl),
        .i2c_sdat     (cam_sda),
        .clock_20k    (),
        .reg_index    ()
    );

    /* verilator lint_off UNUSEDSIGNAL */
    wire _unused_cfg = &{1'b0, camera_pwnd_unused, initial_en_unused};
    /* verilator lint_on UNUSEDSIGNAL */
`endif

    // One pclk register stage on the DVP bus, as in the vendor top.  It adds IO
    // margin and, because pixel_clk is a /2 divided clock, it also sets the
    // phase at which the 16-bit stream is sampled downstream (the vendor-
    // validated phase; without it the BRAM write side samples 180 deg off).
    reg [7:0] cam_data_d0;
    reg       cam_href_d0;
    reg       cam_vsync_d0;

    always @(posedge cam_pclk) begin
        cam_data_d0  <= cam_data;
        cam_href_d0  <= cam_href;
        cam_vsync_d0 <= cam_vsync;
    end

    wire [15:0] pixel_bgr565;

    video_dvp_rgb565 u_dvp (
        .pclk      (cam_pclk),
        .rst_n     (cam_init_done_i),
        .de_i      (cam_href_d0),
        .pdata_i   (cam_data_d0),
        .vs_i      (cam_vsync_d0),
        .pixel_clk (pixel_clk_i),
        .de_o      (pixel_de),
        .pdata_o   (pixel_bgr565)
    );

    // BGR565 -> RGB565 (see RGB_SWAP above).
    assign pixel_rgb565 = RGB_SWAP
        ? {pixel_bgr565[4:0], pixel_bgr565[10:5], pixel_bgr565[15:11]}
        :  pixel_bgr565;

    assign pixel_clk = pixel_clk_i;
    assign cam_reset = cam_reset_i;
    assign cam_init_done = cam_init_done_i;

    // ------------------------------------------------- vsync into pixel domain
    reg [1:0] vsync_sync;
    always @(posedge pixel_clk_i) begin
        vsync_sync <= {vsync_sync[0], cam_vsync};
    end
    assign pixel_vsync = vsync_sync[1];

    // ------------------------------------------ S2 pixel-domain reset/vsync
    // pixel_vsync above stays on pixel_clk_i for the S2 framebuf.  The S1
    // counters deliberately run on cam_pclk (84 MHz) so their sys_clk status
    // synchronizer is covered by the cmos1_pclk/sys_clk async group and no
    // generated-clock CDC path is timed.
    reg [1:0] init_sync;
    wire pixel_rst_i = ~init_sync[1];

    always @(posedge pixel_clk_i) begin
        init_sync <= {init_sync[0], cam_init_done_i};
    end

    assign pixel_rst = pixel_rst_i;

    // -------------------------------------------- capture counters (pclk)
    reg [1:0]  cap_init_sync;
    reg [1:0]  cam_vsync_sync;
    reg        vsync_d;
    reg        de_d;
    reg        pix_toggle;
    reg [31:0] vsync_cnt;
    reg [31:0] line_cnt;
    reg [31:0] pixel_cnt;
    reg [31:0] pclk_cnt;

    wire cap_rst = ~cap_init_sync[1];

    always @(posedge cam_pclk) begin
        cap_init_sync  <= {cap_init_sync[0], cam_init_done_i};
        cam_vsync_sync <= {cam_vsync_sync[0], cam_vsync};
    end

    wire cam_vsync_pclk = cam_vsync_sync[1];

    always @(posedge cam_pclk) begin
        if (cap_rst) begin
            vsync_d    <= 1'b0;
            de_d       <= 1'b0;
            pix_toggle <= 1'b0;
            vsync_cnt  <= 32'd0;
            line_cnt   <= 32'd0;
            pixel_cnt  <= 32'd0;
            pclk_cnt   <= 32'd0;
        end else begin
            vsync_d <= cam_vsync_pclk;
            de_d    <= pixel_de;
            pclk_cnt <= pclk_cnt + 32'd1;

            if (cam_vsync_pclk && !vsync_d) begin
                vsync_cnt <= vsync_cnt + 32'd1;
            end
            if (pixel_de && !de_d) begin
                line_cnt <= line_cnt + 32'd1;
            end
            if (pixel_de) begin
                pix_toggle <= ~pix_toggle;
                if (!pix_toggle) begin
                    pixel_cnt <= pixel_cnt + 32'd1;
                end
            end else begin
                pix_toggle <= 1'b0;
            end
        end
    end

    // ------------------------------------------------------ coherent snapshot
    // 65536 * 11.9 ns = 0.78 ms; the 27 MHz status UART reads a stable value.
    reg [15:0] snap_div;
    reg [31:0] vsync_snap;
    reg [31:0] line_snap;
    reg [31:0] pixel_snap;
    reg [31:0] pclk_snap;

    always @(posedge cam_pclk) begin
        if (cap_rst) begin
            snap_div    <= 16'd0;
            vsync_snap  <= 32'd0;
            line_snap   <= 32'd0;
            pixel_snap  <= 32'd0;
            pclk_snap   <= 32'd0;
        end else begin
            snap_div <= snap_div + 16'd1;
            if (snap_div == 16'hFFFF) begin
                vsync_snap <= vsync_cnt;
                line_snap  <= line_cnt;
                pixel_snap <= pixel_cnt;
                pclk_snap  <= pclk_cnt;
            end
        end
    end

    assign dbg_vsync_cnt = vsync_snap;
    assign dbg_line_cnt  = line_snap;
    assign dbg_pixel_cnt = pixel_snap;
    assign dbg_pclk_cnt  = pclk_snap;

endmodule
